const fs = require('node:fs')
const { withBrowserPage } = require('../module/browserTask')

async function solveTurnstileMin(data, { browser, signal, timeoutMs }) {
  const { url, proxy, siteKey } = data
  if (!url) throw new Error('Missing url parameter')
  if (!siteKey) throw new Error('Missing siteKey parameter')

  return withBrowserPage(
    { browser, proxy, signal, timeoutMs },
    async (page, { on }) => {
      if (proxy?.username && proxy?.password) {
        await page.authenticate({
          username: proxy.username,
          password: proxy.password,
        })
      }

      await page.setRequestInterception(true)
      let rejectRequestFailure
      const requestFailure = new Promise((_, reject) => {
        rejectRequestFailure = reject
      })
      const handleRequest = async request => {
        if (
          [url, `${url}/`].includes(request.url())
          && request.resourceType() === 'document'
        ) {
          await request.respond({
            status: 200,
            contentType: 'text/html',
            body: String(fs.readFileSync('./src/data/fakePage.html')).replace(
              /<site-key>/g,
              siteKey,
            ),
          })
        } else {
          await request.continue()
        }
      }
      on('request', request => {
        void handleRequest(request).catch(rejectRequestFailure)
      })

      const pageOperation = (async () => {
        await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 0 })
        await page.waitForSelector('[name="cf-response"]', { timeout: 0 })
        const token = await page.evaluate(() => {
          try {
            return document.querySelector('[name="cf-response"]').value
          } catch (_error) {
            return null
          }
        })
        if (!token || token.length < 10) throw new Error('Failed to get token')
        return token
      })()

      return Promise.race([pageOperation, requestFailure])
    },
  )
}

module.exports = solveTurnstileMin
